// spec: specs/addbusiness-overseas-location.md (1.2) · кейс: .qa/tests/addbusiness-overseas-location/ADDBIZ-ABROAD-02
// seed: tests/seed.user.spec.ts · ПРОД: «שלב הבא» нажимается с пустым местом — переход не должен случиться.
// Страховка: POST rest/v1/business (создание черновика) обрывается в браузере и не доходит до сервера; его попытка = падение.
import { test, expect } from '@playwright/test';
import {
  ABROAD_TYPE, HALLS_CATEGORY, LOAD, NEXT, REQUIRED_TOAST, STEP2_MARK,
  abroadField, expectNoWrites, openWizard, pick, prepare,
} from './overseas.helpers';

test.use({ storageState: '../auth/user.json', serviceWorkers: 'block' });

test.describe('addbusiness — место бизнеса за границей (шаг 1)', () => {
  test('пустое «מיקום העסק בחו"ל*» → тост «אנא מלא את כל השדות החובה», остаёмся на шаге 1 #75ae6c @desktop @prod-safe', async ({ page, context }) => {
    const ctl = await prepare(context);
    await openWizard(page);
    await page.getByPlaceholder('יופיע ככותרת של המודעה שלך').fill('QA-AUTO abroad');
    await page.getByPlaceholder('תרשום את תיאור העסק שלך, חשוב מאוד יעזור לך למכור!').fill('QA-AUTO בדיקה אוטומטית — לא נשמר בשרת.');
    await page.getByPlaceholder('טלפון ליצירת קשר*').fill('0500000000');
    await page.getByPlaceholder('מחיר').fill('100000');
    await pick(page, 'קטגוריה', HALLS_CATEGORY);
    await pick(page, 'סוג מודעה', ABROAD_TYPE);
    await expect(abroadField(page)).toHaveValue('');

    await page.getByRole('button', { name: NEXT }).click();

    await expect(page.getByText(REQUIRED_TOAST).first(), 'тост об обязательных полях').toBeVisible(LOAD);
    await expect(abroadField(page), 'остались на шаге 1').toBeVisible();
    await expect(page.getByText(STEP2_MARK), 'шаг 2 не открылся').toHaveCount(0);
    await expect(page).toHaveURL(/\/addbusiness(\?|$)/);
    expectNoWrites(ctl);
  });
});
